<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useQuery} from '../lib/query'
import {api,errorText} from '../lib/api'
import {num,pct,direction,stamp,levelPrice} from '../lib/format'
import type {Detail,ChartData} from '../lib/types'
import PageState from '../components/PageState.vue'
import Badge from '../components/Badge.vue'
import EtfChart from '../components/EtfChart.vue'
import ForecastCards from '../components/ForecastCards.vue'
import ResearchPanel from '../components/ResearchPanel.vue'
const route=useRoute(),code=computed(()=>String(route.params.code??'').toUpperCase()),interval=ref('1d'),tab=ref(route.query.tab==='ai'?'ai':'chart'),message=ref(''),busy=ref(false)
const q=useQuery<Detail>(()=>'/api/workspace/instruments/'+encodeURIComponent(code.value)),chart=useQuery<ChartData>(()=>'/api/workspace/instruments/'+encodeURIComponent(code.value)+'/chart?interval='+interval.value+'&limit=500')
const metrics=['ma5','ma10','ma20','ma30','ma60','macd_dif','macd_dea','macd_hist','kdj_k','kdj_d','kdj_j','rsi14','volume_ratio']
async function add(){busy.value=true;try{await api('/api/watchlist/entries',{method:'POST',body:{code:code.value}});message.value='已加入自选；重复操作不会创建多份记录。'}catch(e){message.value=errorText(e)}finally{busy.value=false}}
function distance(value:unknown){const p=typeof value==='number'?value:null;return p!=null&&q.data.value?.quote.price? p/q.data.value.quote.price-1:null}
</script>
<template><PageState :loading="q.loading.value" :error="q.error.value" :empty="!q.data.value" @retry="q.reload"><template v-if="q.data.value"><div class="page-heading"><div><p class="eyebrow">{{q.data.value.instrument.kind}} / {{code}} / {{q.data.value.instrument.theme_l1}}</p><h1>{{q.data.value.instrument.name}} <span class="grade" :data-grade="q.data.value.decision?.grade">{{q.data.value.decision?.grade??'数据异常'}}</span></h1><p>决策快照 {{stamp(q.data.value.decision_time)}} · 指标 {{q.data.value.indicator_as_of??'缺失'}}</p></div><div class="heading-actions"><button class="button" :disabled="busy" @click="add">＋ 加入自选</button><RouterLink class="button" :to="{path:'/holdings',query:{code}}">录入持仓</RouterLink><button class="button primary" @click="tab='ai'">AI 研究</button></div></div><div v-if="message" class="notice" role="status">{{message}}</div><div class="cards"><article class="stat-card"><div class="label">最后观测价格<Badge :value="q.data.value.quote.status"/></div><div class="value" :class="direction(q.data.value.quote.change_ratio)">{{num(q.data.value.quote.price,3)}}<span class="delta">{{pct(q.data.value.quote.change_ratio)}}</span></div><small>{{stamp(q.data.value.quote.source_time)}} · {{q.data.value.quote.source??'无报价'}}</small></article><article class="stat-card"><div class="label">最近支撑 · 当前快照</div><div class="value">{{num(levelPrice(q.data.value.support_resistance?.nearest_support),3)}}</div><small>相对现价 {{pct(distance(levelPrice(q.data.value.support_resistance?.nearest_support)))}}</small></article><article class="stat-card"><div class="label">最近压力 · 当前快照</div><div class="value">{{num(levelPrice(q.data.value.support_resistance?.nearest_resistance),3)}}</div><small>相对现价 {{pct(distance(levelPrice(q.data.value.support_resistance?.nearest_resistance)))}}</small></article><article class="stat-card"><div class="label">我的每份成本</div><div class="value">{{num(q.data.value.holding?.cost_price,3)}}</div><small>持仓盈亏 <span :class="direction(q.data.value.holding?.pnl_ratio)">{{pct(q.data.value.holding?.pnl_ratio)}}</span> · 未录入不估算</small></article></div><div class="section-tabs"><button :class="{active:tab==='chart'}" @click="tab='chart'">技术图表</button><button :class="{active:tab==='ai'}" @click="tab='ai'">AI 研究与证据</button></div><template v-if="tab==='chart'"><div class="card"><div class="card-header"><div><h2>K 线与技术指标</h2><p>统一 Python 公式 · 已确认日 K 支撑压力快照，与最新报价可能不同步</p></div><div class="range-buttons"><button v-for="i in ['1d','30m','60m']" :key="i" :class="{active:interval===i}" @click="interval=i">{{i==='1d'?'日线':i==='30m'?'30 分钟':'60 分钟'}}</button></div></div><PageState :loading="chart.loading.value" :error="chart.error.value" :empty="!chart.data.value?.available" title="该周期暂无合格数据" :description="chart.data.value?.reason??'日线不会冒充分钟线；请检查数据同步状态。'" @retry="chart.reload"><EtfChart v-if="chart.data.value?.available" :data="chart.data.value" :cost="q.data.value.holding?.cost_price"/></PageState></div><div v-if="chart.data.value?.core_snapshot_match===false||chart.data.value?.history_truncated" class="notice warning-notice">图表历史与最新指标快照未完全对齐或历史已截断，请核对数据版本；不能把它当作决策快照的精确历史回放。</div><div v-if="q.data.value.holding&&!chart.data.value?.cost_overlay_allowed" class="notice">当前价格基准不允许直接叠加持仓成本线，避免复权口径混淆。</div><div class="card"><div class="card-header"><div><h2>指标快照数值</h2><p>{{q.data.value.indicator_version}} · {{q.data.value.indicator_as_of}} · 不由 AI 计算</p></div></div><div class="card-body metrics-grid"><div v-for="key in metrics" :key="key" class="metric-box"><small>{{key.toUpperCase()}}</small><strong class="mono">{{num(q.data.value.indicator_values[key],key.startsWith('macd')?6:2)}}</strong></div></div></div><div class="card"><div class="card-header"><div><h2>未来研究情景</h2><p>预测与真实 K 线分离；区间不代表承诺，历史频率不等于校准概率。</p></div></div><div class="card-body"><ForecastCards :forecasts="q.data.value.forecasts"/></div></div></template><ResearchPanel v-else :code="code"/></template></PageState></template>
